import{_ as a,C as o,o as i,c as r,j as p,a as n,E as l,a5 as s}from"./chunks/framework.DNkHA0lr.js";const k=JSON.parse('{"title":"多巴胺流行病：社会如何未能进行长期思考","description":"","frontmatter":{"title":"多巴胺流行病：社会如何未能进行长期思考","originalTitle":"The Dopamine Epidemic: How Society Failed To Think Long Term","date":"2024-11-16","originalUrl":"https://thedankoe.com/letters/the-dopamine-epidemic-how-society-failed-to-think-long-term/","minutes":13,"sourceHash":"143249f32c98ce72ddad903fa654fb664159fa5ff431671f9c47ff8b479cb049","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-dopamine-epidemic-how-society-failed-to-think-long-term/"}]]},"headers":[],"relativePath":"letters/the-dopamine-epidemic-how-society-failed-to-think-long-term.md","filePath":"letters/the-dopamine-epidemic-how-society-failed-to-think-long-term.md"}'),m={name:"letters/the-dopamine-epidemic-how-society-failed-to-think-long-term.md"};function h(d,e,c,g,u,f){const t=o("ArticleMeta");return i(),r("div",null,[e[0]||(e[0]=p("h1",{id:"多巴胺流行病-社会如何未能进行长期思考",tabindex:"-1"},[n("多巴胺流行病：社会如何未能进行长期思考 "),p("a",{class:"header-anchor",href:"#多巴胺流行病-社会如何未能进行长期思考","aria-label":'Permalink to "多巴胺流行病：社会如何未能进行长期思考"'},"​")],-1)),l(t),e[1]||(e[1]=s('<p><a href="https://www.youtube.com/embed/Bq9de46Uh4I?si=KWvcxS9utqqywvOA" target="_blank" rel="noreferrer">观看原文视频</a></p><p>广告：在我们开始之前，一人企业启动指南（One-Person Business Launchpad）现已开放预购，直到黑色星期五周末。在此期间将享受5折优惠。如果你发现自己在问，“好吧，我喜欢一人企业这个概念……但<em>我到底该怎么开始呢？</em>”那就来这里入手吧。</p><p>在里面，我详细拆解了从注册公司到最佳使用软件，再到如何赚到你的第一笔5000美元的一切内容。</p><p><a href="https://stan.store/thedankoe/p/the-oneperson-business-launchpad--your-first-5k" target="_blank" rel="noreferrer">点这里获取。</a></p><p>–––</p><p>社交媒体是社交的快餐。</p><p>色情内容是亲密关系的快餐。</p><p>电子游戏是成就感的快餐。</p><p>Netflix是娱乐的快餐。</p><p>快餐本身是脂肪、糖和盐的组合——这些曾经极其稀缺的成分——它们以无数种不同的方式被组合和测试，以找出哪种搭配能让消费者不断回头再吃。</p><p>为了理解我们正在经历的这场廉价多巴胺流行病，我们需要一段简短的历史课。</p><p>给社会分类的一种方式是看其技术经济基础。换句话说，就是该社会用来满足基本需求所依靠的基本生产方式（比如马拉犁与机器的区别）。共有5种：</p><ul><li><strong>采集狩猎型</strong>——狩猎和采集。男性狩猎，女性采集。</li><li><strong>园艺型</strong>——简单的种植。女性生产了大部分食物，社会的神祇变为女性。</li><li><strong>农耕型</strong>——用动物拉犁。由于流产率增加，女性无法继续从事耕作，于是她们的角色发生了变化，社会的神祇变为男性。80%的农耕社会依赖男性奴隶劳动力。</li></ul><p>这标志着文化的巨大转变。由于耕犁对女性来说是一种达尔文式的劣势，她们转变了角色，开始承担更多“传统”的居家和育儿角色。由于有了犁，食物开始变得充裕，男性因此有了更多的空闲时间去思考和追求新的兴趣。（正是在这个时候，文字和数学被发明出来。）</p><p>农耕型之后的最后两种基础是<em>工业型</em>和<em>信息型</em>。</p><p>要注意的是，<em>人属（homo genus）</em>物种大约在200万年前出现，而<em>智人（homo sapiens）</em>大约在30万年前出现。工业时代始于300年前（仅占人类进化历程的千分之一），这意味着我们的大脑显然还没有适应接下来发生的一切。</p><p>随着工业时代的发展，脂肪、糖和盐变得越来越不稀缺。我们可以在沿海地区交换盐，并以惊人的速度生产脂肪和糖。</p><p>在1920到1950年间，事情继续发生变化。流水线和朝九晚五的工作出现了（多谢亨利·福特），人类的工作方式开始转变为我们今天所熟知的劳动力模式。简而言之，人类拥有了更多的金钱和潜力。</p><p>1950年后，快餐连锁店开始遍地开花。接着，信息时代到来了。电视黄金时代让信息传播得更加广泛。</p><p>再往后，是互联网。信息开始像野火一样疯狂增长和传播。快进到现在，我们有了谷歌、Facebook等其他即将崛起的巨型公司，在通往顶端的竞赛中彼此角逐。</p><p>这些一开始并非都是坏事，但对权力的渴望使得技术以相当糟糕的激励机制演变。一切都太新了。此前从未有人这样做过。谁能猜到它最终会变得如此具有破坏性？</p><p>所有这些跨越各个领域的巨型公司——不仅仅是互联网公司——都在试图不惜一切代价“赢得这场游戏”，即便这意味着以牺牲客户的福祉为代价。</p><h3 id="脂肪、糖和盐。" tabindex="-1">脂肪、糖和盐。 <a class="header-anchor" href="#脂肪、糖和盐。" aria-label="Permalink to &quot;脂肪、糖和盐。&quot;">​</a></h3><p>人类没有适应大量获取这些稀缺资源。我们是为生存而适应的。当发现这些稀缺成分时，它们会向我们的大脑释放多巴胺，以此表明我们找到了有助于生存的东西。</p><p>一旦公司发现了这种机制，他们就可以测试并创造出这些成分的组合，从而最大化顾客的愉悦感，让他们不断回头再来。上瘾。</p><p>四层肉饼汉堡。搭配48盎司超大杯超美味碳酸饮料的芝士脆玉米卷卡布里托。</p><p>互联网公司也纷纷效仿。他们采用了广告变现模式，很快发现两极化和煽动性的标题能最有效地抓住注意力。现在他们只需要把用户“喜欢”的更多内容，推送到一块随手可及的屏幕上。你好，“为你推荐”页面！</p><ul><li><strong>脂肪</strong> = 制造恐慌</li><li><strong>糖</strong> = 快速且诱人的承诺</li><li><strong>盐</strong> = 绝对化的极端观点</li></ul><p>互联网公司会测试这些成分的组合，然后算法就会一直喂给我们，直到我们变得“精神肥胖”为止。恐惧驱动的内容会向我们的大脑释放多巴胺，并使我们的思维变得狭隘，因为我们“需要”这些信息以备未来生存之需。</p><p>现在，我们就来到了这一步。</p><p>快钱、快性、快知识、快食物、快娱乐。</p><p>一颗一开始感觉良好，但之后感觉糟糕的定时炸弹。</p><p>但故事还没结束。</p><p>多巴胺并<em>不全是坏东西</em>。</p><p>毕竟，我们正经历着一场第二次文艺复兴（文艺复兴发生在黑暗时代之后）。对于那些有意识、有意图地追求真理与成长的人来说，互联网和社交媒体正是让他们能够做自己热爱的工作、重新掌控自己生活的关键。</p><h2 id="想要更多-的分子——多巴胺如何运作" tabindex="-1">“想要更多”的分子——多巴胺如何运作 <a class="header-anchor" href="#想要更多-的分子——多巴胺如何运作" aria-label="Permalink to &quot;“想要更多”的分子——多巴胺如何运作&quot;">​</a></h2><blockquote><p>从广义上讲，说某件事“重要”，其实就是在说它与多巴胺相关。为什么？因为在多巴胺所做的众多事情中，有一项是充当一种预警系统，用来发现任何可能帮助我们生存的东西。——丹尼尔·Z·利伯曼（Daniel Z. Lieberman）</p></blockquote><p>大多数人并不理解多巴胺。</p><p>正因为他们不理解它，他们很难注意到自己的不良行为，也很难以一种有利于自身发展的方式去纠正它。</p><p>多巴胺不是愉悦分子。</p><p>多巴胺是“<em>想要更多</em>”的分子。</p><p>但多巴胺并不是唯一一种根据我们的行为和感知来提供反馈的神经递质。</p><p>神经递质有两种类型：</p><p><strong>1）向下的化学物质，也就是“当下”化学物质</strong></p><p>当你向下看时，你看到了什么？你看到的是你<em>周身</em>空间之内的一切。触手可及的事物。你能掌控的事物。</p><p>与你眼前空间相关的“当下”化学物质，让你能够<em>品味、享受，或者对你正在经历的事物做出战斗或逃跑的反应。</em></p><p>催产素、去甲肾上腺素、肾上腺素、血清素、内啡肽和内源性大麻素。</p><p><strong>2）向上的化学物质：多巴胺</strong></p><p>向外看。抬头看看天空。看看互联网。看看商店的橱窗。回想一下你愉快假期的记忆。</p><p>这些事物有什么共同点？</p><p><em>都是你没有拥有的东西。</em></p><p>是存在于你身外空间中的东西。</p><p>多巴胺会驱使你去追求、去掌控、去占有那些你没有但想要的东西，因为这些东西对你的生存可能有用。好吧，也许现在没用，但在过去肯定有用。更多的资源。更多的性伴侣和后代。一匹马和一把剑，用来穿越险恶地形，在未知的土地上发现更多东西。</p><p><strong>那么，问题出在哪里？我们该怎么办？</strong></p><p>问题在于，由博弈论原理所打造出的信息泛滥让我们承受了过量的多巴胺，以至于我们已经与现实脱节。</p><p>人际关系会因此受损，因为一旦你借助多巴胺驱动的动力“占有”了一位伴侣，你就没能重新调整自己的习惯，去在热恋期过后珍惜和品味这段关系。</p><p>在上一封信<a href="/letters/the-meaning-crisis-how-to-do-something-that-matters">《意义危机》</a>中，我们讨论了如何通过<em>存在（being）、行动（doing）和成为（becoming）</em>来重新连接现实。</p><p>多巴胺是一种“期待分子”。所以，如果我们想要享受我们已经拥有的东西，就必须训练我们的大脑摆脱面向未来的倾向，重新回到持续的当下导向状态。</p><p>换句话说，多<em>存在</em>一些。沉浸在当下这一刻中。养成一种正念习惯。去散步。凝视一片叶子，从这样一个小小的绿色物体中所包含的那张半透明的生命网络里找到喜悦。这可能就是你最缺失的那个主要习惯。</p><p>正因如此，多巴胺戒断才有帮助。你消除掉所有“你没有拥有的东西”的来源，你会变得极度无聊。你唯一的选择就是从眼前的事物中寻找兴趣。像孩子一样重新看待这个世界。</p><p>但是，你不一定非要做多巴胺戒断。</p><p>你只需要改变你接触、使用和利用（杠杆化）那些正在摧毁大多数人生活的技术的方式。</p><h2 id="整体解决方案-长期满足感" tabindex="-1">整体解决方案：长期满足感 <a class="header-anchor" href="#整体解决方案-长期满足感" aria-label="Permalink to &quot;整体解决方案：长期满足感&quot;">​</a></h2><p>事情是这样的。</p><p>多巴胺不是一种坏的化学物质。</p><p>它是成功<em>和</em>失败背后的驱动力。</p><p>区别在于长期满足感与短期满足感之间的差异。</p><p>这句话不能被轻视，因为这种差异是<em>巨大的</em>。</p><p>短期满足感——即廉价多巴胺——会导致熵增。</p><p>长期满足感——即<em>赢得的</em>多巴胺——会导致负熵（centropy）。</p><p>就我们所关心的层面而言，<strong>熵增</strong>是指逐渐陷入混乱、不确定和无序的状态。可以想象：焦虑、不堪重负，以及那种似乎只会越来越糟的、无法逃脱的负面思维泡泡，这通常是因为我们在表面停留太久，无法再理解这个世界。</p><p><strong>负熵（centropy）</strong>，即逆转熵增，是我们作为人类都在面对的一场向上攀登的斗争。它意味着维持、创造或改善秩序与确定性。可以想象：挑战如何带来充实感、心流，以及一种对自己生活的目的感或掌控感。</p><p>由于社交媒体在我们生活中占据如此庞大且几乎不可或缺的一部分，我想重点谈谈它。</p><p>尽管社交媒体很容易迅速变得有毒，但很难否认它是我们工作方式（包括现在和未来）、沟通方式，以及我们如何与大家保持信息同步以便作为一个社会共同进步的重要组成部分。当然，最后这一点正在被严重利用。如果人们把自己的意义构建（sensemaking）交由那些想要最大化你在平台上停留时间、利用你大脑运作机制的公司来掌控，那么似乎没有人能真正与大家保持同步。</p><p>这就带来了一个问题：</p><p>成为一个被精心策划的算法奴役的人，会让你不断接收那些带来短期满足感的内容，使你始终处于压力和生存应激状态。恐惧与欲望的结合会把你从当下拉走，熵增随之加剧。你以为那只是一条无害的帖子，但实际上，它是你一起看完的50条短帖组合，悄无声息地在你的脑海中引发了混乱。你在退步。你停滞不前。你把自己锁进了某种政治意识形态和僵化观点的框架中，而这些东西根本无法帮助你在生活中实现任何有价值的目标。</p><p>如今，如果社交媒体公司的激励机制有所不同，我们所有人本可以处于一个更好的境地。但我们现在已经陷得太深，明智的做法是，不要相信任何人——尤其是某个巨型企业——会去提升你的生活质量。那是你自己的事。</p><h3 id="为成功创造新的数字环境" tabindex="-1">为成功创造新的数字环境 <a class="header-anchor" href="#为成功创造新的数字环境" aria-label="Permalink to &quot;为成功创造新的数字环境&quot;">​</a></h3><p>你听过“破窗理论”吗？</p><p>它相当有趣。</p><p>简单来说，曾经有一个实验，研究了两种不同的环境：一种是故意打破的窗户，另一种看起来干净整洁。</p><p>在他们安装了新窗户并把区域打理干净的地方，<em>犯罪率下降了约50%</em>。</p><p>在他们打破窗户、制造混乱的地方，<em>犯罪率上升了</em>。</p><p>为什么会这样？</p><p>因为你的环境在很大程度上塑造了你的行为。</p><p>在互联网上，我们每天都在把自己的大脑暴露在一个有着成千上万块破窗的环境里。</p><p>数字环境对你思维的塑造速度比物理环境快得多，因为可获取的信息量更大。</p><p>重点来了：</p><p>很少有人意识到，<em>是你自己选择把自己置于那种环境中，而作为一个有意图的个体，你可以创造一个新的环境。</em></p><h2 id="成为价值创造者——赢得的多巴胺人生" tabindex="-1">成为价值创造者——赢得的多巴胺人生 <a class="header-anchor" href="#成为价值创造者——赢得的多巴胺人生" aria-label="Permalink to &quot;成为价值创造者——赢得的多巴胺人生&quot;">​</a></h2><p>社交媒体是我们能获得的最伟大的技术之一。</p><p>我不是想炫耀（好吧，我确实有点想），但社交媒体对我来说很少是有毒和煽动性的。当然，我也会掉进一些政治的兔子洞和糟糕的观点里，但95%的时间里，社交媒体既是我取得非传统成功的发动机，也是燃料。</p><p>想想看。社交媒体让你可以：</p><ul><li><strong>几乎学习任何东西</strong>，挑战你的理解，寻求新的视角以更接近真相。</li><li><strong>建立一个企业或独立的收入来源。</strong> 你间接接触到55亿人，你可以<em>帮助</em>他们，换取另一种形式的价值，比如金钱或注意力，而这些又可以用来引导更多人走上长期满足的道路，从而产生连锁反应。 <ul><li><a href="https://stan.store/thedankoe/p/the-oneperson-business-launchpad--your-first-5k" target="_blank" rel="noreferrer">一人企业发射台</a>用简单的方式拆解了这一点。它的目标是帮助你围绕你的主要技能或兴趣，用5个客户赚到你的第一个5000美元。</li></ul></li><li><strong>找到潜在的雇主、投资者、团队成员或人脉。</strong> 创造高价值内容现在替你完成了这些繁重的工作。</li></ul><p>这些都是<em>逆熵</em>的。它们需要时间和精力。它们通过提供有意义的输入和输出，逆转了你已经习以为常的熵增和混乱。它们是赢得的多巴胺。它们带来更大的复杂性和秩序，让你能够发现更多机会、解决更多问题、创造更多价值，并以有意义的方式获利。</p><p>既然社交媒体公司不会改变它们自己的激励机制，那就得靠你来创造你自己的激励机制。你自己的秩序。你自己的环境。你自己成功的催化剂。</p><p>以下是具体方法，分三步：</p><h3 id="_1-打理你的数字环境" tabindex="-1">1）打理你的数字环境 <a class="header-anchor" href="#_1-打理你的数字环境" aria-label="Permalink to &quot;1）打理你的数字环境&quot;">​</a></h3><p>第一个罪魁祸首是短内容。</p><p>它对获取快速见解可能有用，但很容易演变成一个充满段子和无意义内容的兔子洞。</p><p>我们不再用那些不以成为《纽约时报》畜销书或制造最煽动性的诱导点击标题为激励的书籍和文章来挑战我们的信念和理解。如果他们的主要意图是地位（<em>主要</em>意图，每个人都在以某种方式追逐地位），那么他们传播的信息就会为此量身定制。</p><p><em>你在网上花费的大部分时间，应该用在那些能挑战、拓展并滋养你视角的长内容上。</em></p><p>读得更长。阅读更难的概念。阅读那些<em>不会</em>只为让你感觉良好而印证你信念的东西。阅读很容易被误认为是精神层面的自我满足，但它远不止于此。</p><p>我甚至会说，你未来大部分的成功都取决于这一个习惯：读更长的东西。</p><p>换句话说，消费那些有助于你成长的内容，而不是反过来被内容消耗。</p><ul><li>取关那些你<em>明知</em>无助于你成长的账号。</li><li>找到你喜欢读的长文、视频和播客。</li><li>在社交媒体上关注这些长内容创作者——他们写的短内容质量更高，能帮你填补知识空缺。</li><li>如果你愿意，可以留意这些人互动的对象，并也去关注他们。</li><li>算法会开始给你推送更好的内容。对那些无益于你的内容，果断取关或屏蔽。</li></ul><p>你越用心打理你的数字环境，就越能减少熵增，促进逆熵。</p><h3 id="_2-专注于一个有意义的项目" tabindex="-1">2）专注于一个有意义的项目 <a class="header-anchor" href="#_2-专注于一个有意义的项目" aria-label="Permalink to &quot;2）专注于一个有意义的项目&quot;">​</a></h3><blockquote><p>去做一件伟大的事，你的人脉自然会随之出现。——纳瓦尔·拉维康特（Naval Ravikant）</p></blockquote><p>现在你已经有了良好的、逆熵的输入，你还需要良好的逆熵输出。</p><p>多巴胺不只来自消费信息，因为信息不仅限于你读到和听到的东西。</p><p>你的习惯……你所<em>做</em>的事……会把你的思维塑造向正面或负面的方向。你可以选择投入一个能拼成你理想生活方式的项目，也可以用段子和快感来填补你的无聊，而这只会导向混乱和无序。</p><p>为什么要建立一个项目？</p><p>因为它们是有序的。它们能框定你的思维。它们让你把你的输入——你消费的信息——引导转化为某种<em>真实而有价值</em>的东西。某种你可以从中获得收入的东西。某种你可以反哺给这个世界的东西。</p><p>如果你没有一个正在建立的项目，那很可能你已经在为别人建立项目了……由某个老师或雇主分配给你的项目。你会花8个小时去建造他们的梦想，却不愿花1个小时去建造你自己的。</p><p>是的，只需要1个小时，就足以彻底重置你的心理健康状态。</p><h3 id="_3-赢得你的掌控与自由" tabindex="-1">3）赢得你的掌控与自由 <a class="header-anchor" href="#_3-赢得你的掌控与自由" aria-label="Permalink to &quot;3）赢得你的掌控与自由&quot;">​</a></h3><p>那么，你要建造什么？</p><p>好吧，我假设你是从零开始的。</p><p>你没什么存款。你也许有一些技能。你有雄心，但不知道从何处开始建立自己的东西。</p><p>事实是，我们已经不在工业时代了，我们处在信息时代。</p><p>找一份工作、投资你的储蓄，<em>并不是唯一的选择。</em></p><p>事实上，如果你还没察觉到的话，人们正在对传统道路所承诺的“保障未来”失去信任。这是最糟糕的选项之一，因为你的时间、精力和情绪健康都被掌控在一个老板手里。</p><p>所有新的财富都正在数字空间中被创造出来。</p><p>这是思想的空间。</p><p>这是创作者经济。</p><p>一个人们不再受限于人脉或物理位置的地方，因为只要有网络连接，他们就能触达任何人。</p><p>而如果你拥有正确的技能——写作、营销和构建——你要做的只是把你建造的东西，展示给那一小部分认为你所建造之物有价值的人。</p><p>所以：</p><p>创造你想在这个世界上看到的内容。</p><p>建造你想在这个世界上看到的产品。</p><p>创造能拉伸你的思维、并在你写作过程中促使你成长的内容。通过打造受众，吸引与你志趣相投的人。这些正是你能帮助最多的人。</p><p>建造有助于他人发展和自我实现的产品。向你的受众推广你的产品——因为你已经不再有老板替你做这件事了——并赢得你的自由。</p><p>这封信就到这里。</p><hr><p><a href="/en/letters/the-dopamine-epidemic-how-society-failed-to-think-long-term">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',136))])}const _=a(m,[["render",h]]);export{k as __pageData,_ as default};
